export const projectManagementTextbookHtml = "\n  <div class=\"tkd-page-scope font-sans antialiased bg-[#FAF8F6] text-[#333333]\">\n\n    <!-- COVER HEADER CHO BẢN IN HOẶC XUẤT PDF A4 -->\n    <div class=\"print-document-header hidden print:block text-center border-b-2 border-[#8B1E2D] pb-4 mb-6\">\n      <div class=\"text-[12pt] font-semibold text-[#8B1E2D] tracking-wider uppercase\">TRƯỜNG CAO ĐẲNG KINH TẾ TP. HỒ CHÍ MINH — KHOA QUẢN TRỊ KINH DOANH</div>\n      <h1 class=\"text-[20pt] font-extrabold text-[#111827] uppercase tracking-tight mt-2 mb-1\">\n        GIÁO TRÌNH QUẢN TRỊ DỰ ÁN (MH38)\n      </h1>\n      <div class=\"text-[11pt] text-[#4B5563] italic\">\n        Tài liệu học tập chính quy bậc Cao đẳng &amp; Đại học — Chủ biên: ThS. NGUYỄN THỊ TRÚC PHƯƠNG\n      </div>\n      <div class=\"text-[10pt] text-[#6B7280] mt-2 flex justify-between items-center border-t border-[#E5E7EB] pt-1\">\n        <span>Mã học phần: MH38 (3 tín chỉ / 45 tiết)</span>\n        <span class=\"print-timestamp\">Năm học: <span class=\"js-current-year\"></span></span>\n        <span>Cổng học liệu số: NGUYỄN THỊ TRÚC PHƯƠNG</span>\n      </div>\n    </div>\n\n    <!-- HEADER BANNER ONLINE LUXURY RED TONE -->\n    <header class=\"no-print w-full bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#C62828] text-white py-8 sm:py-10 px-4 shadow-md border-b border-[#FCEEEF]/20\">\n      <div class=\"max-w-5xl mx-auto text-center space-y-2\">\n        <span class=\"inline-block px-3 py-1 bg-white/10 rounded-full text-xs font-semibold tracking-wider uppercase mb-1 border border-white/20\">\n          Chương Trình Đào Tạo Chuẩn Học Thuật — Mã Môn: MH38\n        </span>\n        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight\">\n          GIÁO TRÌNH QUẢN TRỊ DỰ ÁN\n        </h1>\n        <p class=\"text-sm sm:text-base text-red-100 max-w-2xl mx-auto font-light\">\n          Cẩm nang học thuật toàn diện theo chuẩn Viện Quản trị Dự án Hoa Kỳ (PMI): Thẩm định tài chính (NPV, IRR, PP, PI), Cấu trúc WBS, Sơ đồ mạng CPM/PERT và Phương pháp Quản lý giá trị thu được (EVM).\n        </p>\n        <div class=\"pt-2 flex flex-wrap justify-center gap-3 text-xs text-white/90\">\n          <span class=\"bg-black/20 px-3 py-1 rounded\">Chủ biên: <strong>ThS. Nguyễn Thị Trúc Phương</strong></span>\n          <span class=\"bg-black/20 px-3 py-1 rounded\">Thời lượng: <strong>45 Tiết (3 Tín chỉ)</strong></span>\n          <span class=\"bg-black/20 px-3 py-1 rounded\">Trình độ: <strong>Cao đẳng &amp; Đại học QTKD</strong></span>\n        </div>\n      </div>\n    </header>\n\n    <!-- THANH ĐIỀU HƯỚNG MỤC LỤC NHANH (STICKY NAV) -->\n    <nav class=\"no-print sticky top-0 z-40 bg-white/95 backdrop-blur-md border-b border-[#E5E7EB] shadow-sm py-2 px-4\">\n      <div class=\"max-w-5xl mx-auto flex items-center justify-between gap-4 overflow-x-auto text-xs sm:text-sm font-medium text-gray-700\">\n        <span class=\"font-bold text-[#8B1E2D] whitespace-nowrap flex items-center gap-1\">\n          <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253\"></path></svg>\n          Mục lục:\n        </span>\n        <div class=\"flex items-center gap-2 sm:gap-4 whitespace-nowrap\">\n          <a href=\"#loi-gioi-thieu\" class=\"hover:text-[#8B1E2D] hover:underline\">Lời mở đầu</a>\n          <a href=\"#chuan-dau-ra\" class=\"hover:text-[#8B1E2D] hover:underline\">Chuẩn đầu ra</a>\n          <a href=\"#chuong-1\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 1: Tổng quan</a>\n          <a href=\"#chuong-2\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 2: Lựa chọn dự án</a>\n          <a href=\"#chuong-3\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 3: Tổ chức dự án</a>\n          <a href=\"#chuong-4\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 4: Kế hoạch &amp; Ngân sách</a>\n          <a href=\"#chuong-5\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 5: Tiến độ CPM/PERT</a>\n          <a href=\"#chuong-6\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 6: Nguồn lực</a>\n          <a href=\"#chuong-7\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 7: Kiểm soát EVM</a>\n          <a href=\"#chuong-8\" class=\"hover:text-[#8B1E2D] hover:underline\">Chương 8: Kết thúc dự án</a>\n          <a href=\"#tai-lieu-tham-khao\" class=\"hover:text-[#8B1E2D] hover:underline\">Tài liệu tham khảo</a>\n        </div>\n      </div>\n    </nav>\n\n    <!-- NỘI DUNG CHÍNH (MAIN BODY CONTAINER) -->\n    <main class=\"max-w-5xl mx-auto px-4 py-8 space-y-12 leading-relaxed\">\n\n      <!-- PHẦN THÔNG TIN TỔNG QUAN HỌC PHẦN -->\n      <section id=\"loi-gioi-thieu\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b border-[#FCEEEF] pb-4\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Thông tin học phần chính quy</span>\n          <h2 class=\"text-xl sm:text-2xl font-bold text-[#111827] mt-1\">LỜI GIỚI THIỆU &amp; MỤC TIÊU HỌC PHẦN</h2>\n        </div>\n        \n        <div class=\"space-y-4 text-sm sm:text-base text-gray-700\">\n          <p>\n            Giáo trình <strong>Quản trị dự án (Mã học phần: MH38)</strong> được biên soạn theo chương trình khung đào tạo chuyên ngành Quản trị kinh doanh của Trường Cao đẳng Kinh tế Thành phố Hồ Chí Minh, cập nhật các chuẩn mực quản lý dự án hiện đại của <em>Viện Quản lý Dự án Hoa Kỳ (Project Management Institute - PMI)</em>.\n          </p>\n          <p>\n            Trong nền kinh tế tri thức và hội nhập toàn cầu, các hoạt động kinh doanh ngày càng được tổ chức dưới dạng các <em>\"dự án\"</em> với mục tiêu cụ thể, ràng buộc khắt khe về thời gian hoàn thành, ngân sách chi phí giới hạn và tiêu chuẩn chất lượng nghiêm ngặt (Ràng buộc Tam giác vàng - Triple Constraints). Học phần cung cấp cho sinh viên toàn bộ quy trình quản lý dự án từ giai đoạn khởi tạo, thẩm định hiệu quả tài chính (PP, NPV, IRR, PI), lập cấu trúc phân chia công việc (WBS), thiết lập tiến độ bằng sơ đồ mạng (Gantt, CPM, PERT), phân bổ và cân bằng nguồn lực, đến hệ thống kiểm soát chi phí - tiến độ bằng kỹ thuật <strong>Earned Value Management (EVM)</strong> và thủ tục bàn giao, kết thúc dự án chuyên nghiệp.\n          </p>\n        </div>\n\n        <!-- MỤC TIÊU HỌC PHẦN -->\n        <div id=\"chuan-dau-ra\" class=\"grid grid-cols-1 md:grid-cols-3 gap-4 pt-2\">\n          <div class=\"p-4 rounded-lg bg-[#FAF8F6] border-l-4 border-[#8B1E2D] space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">1</span>\n              Chuẩn Kiến thức (Knowledge)\n            </h3>\n            <p class=\"text-xs text-gray-600\">\n              Nắm vững bản chất chu kỳ sống dự án; các phương pháp thẩm định dòng tiền dự án; cấu trúc WBS; nguyên lý đường găng CPM; tính toán thời gian xác suất PERT và các chỉ số đo lường hiệu quả EVM (CV, SV, CPI, SPI).\n            </p>\n          </div>\n          <div class=\"p-4 rounded-lg bg-[#FAF8F6] border-l-4 border-[#8B1E2D] space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">2</span>\n              Chuẩn Kỹ năng (Skills)\n            </h3>\n            <p class=\"text-xs text-gray-600\">\n              Thành thạo kỹ năng lập bảng kế hoạch công việc WBS; vẽ sơ đồ mạng AOA/AON; xác định thời gian sớm/muộn ($ES, EF, LS, LF$), thời gian dự trữ ($TF$); phát hiện đường găng và lập báo cáo kiểm soát chi phí dự án.\n            </p>\n          </div>\n          <div class=\"p-4 rounded-lg bg-[#FAF8F6] border-l-4 border-[#8B1E2D] space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">3</span>\n              Năng lực Tự chủ &amp; Trách nhiệm\n            </h3>\n            <p class=\"text-xs text-gray-600\">\n              Phát triển kỹ năng lãnh đạo đội ngũ dự án, giải quyết xung đột nguồn lực, tư duy quản lý rủi ro và tuân thủ các chuẩn mực đạo đức nghề nghiệp trong quản lý ngân sách và hồ sơ nghiệm thu.\n            </p>\n          </div>\n        </div>\n\n        <!-- DANH MỤC THUẬT NGỮ VÀ CHỮ VIẾT TẮT -->\n        <div class=\"pt-4 border-t border-gray-100\">\n          <h4 class=\"text-xs font-bold text-gray-800 uppercase tracking-wider mb-2\">Danh mục ký hiệu và chữ viết tắt chuyên môn</h4>\n          <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs\">\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">WBS:</strong> Work Breakdown Structure (Cấu trúc phân chia công việc)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">CPM:</strong> Critical Path Method (Phương pháp đường găng)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">PERT:</strong> Program Evaluation &amp; Review Technique</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">NPV:</strong> Net Present Value (Hiện giá ròng)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">IRR:</strong> Internal Rate of Return (Suất hoàn vốn nội bộ)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">EVM:</strong> Earned Value Management (Quản lý giá trị thu được)</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">PV / EV / AC:</strong> Planned Value / Earned Value / Actual Cost</div>\n            <div class=\"bg-gray-50 p-2 rounded\"><strong class=\"text-[#8B1E2D]\">CPI / SPI:</strong> Cost Performance Index / Schedule Performance Index</div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 1: TỔNG QUAN VỀ QUẢN TRỊ DỰ ÁN -->\n      <!-- ========================================== -->\n      <section id=\"chuong-1\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 1 (MH38.01)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">TỔNG QUAN VỀ QUẢN TRỊ DỰ ÁN</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">1.1. Khái Niệm Đầu Tư và Dự Án Đầu Tư</h3>\n            <p>\n              <strong>Đầu tư</strong> là việc hy sinh, chi dùng các nguồn lực (tiền bạc, tài sản, thời gian, trí tuệ) ở hiện tại nhằm thu về những kết quả và lợi ích lớn hơn trong tương lai. Lợi ích thu được có thể là lợi ích tài chính (lợi nhuận, dòng tiền) hoặc lợi ích kinh tế - xã hội.\n            </p>\n            <p class=\"mt-2\">\n              <strong>Dự án (Project)</strong> là một tập hợp các công việc, hoạt động có liên quan chặt chẽ với nhau, được thực hiện có kế hoạch nhằm tạo ra một sản phẩm, dịch vụ hoặc kết quả <em>độc nhất vô nhị (unique)</em>, trong giới hạn về <em>thời gian</em> và <em>nguồn lực</em> xác định.\n            </p>\n            <blockquote class=\"my-3 p-4 bg-[#FCEEEF]/30 border-l-4 border-[#8B1E2D] rounded-r text-gray-800 italic\">\n              \"Dự án là một nỗ lực tạm thời (temporary endeavor) được triển khai nhằm tạo ra một sản phẩm, dịch vụ hoặc kết quả mang tính chất duy nhất.\"\n              <footer class=\"text-xs text-gray-500 font-semibold mt-1\">— Project Management Institute (PMI), PMBOK® Guide</footer>\n            </blockquote>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">1.2. Các Đặc Trưng Cơ Bản của Dự Án</h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">1. Tính tạm thời (Temporary):</strong> Mọi dự án đều có thời điểm bắt đầu và thời điểm kết thúc xác định. Dự án hoàn thành khi mục tiêu đã đạt được hoặc bị hủy bỏ khi mục tiêu không còn khả thi.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">2. Tính duy nhất (Unique):</strong> Sản phẩm hoặc kết quả đầu ra của dự án luôn có điểm khác biệt so với tất cả các sản phẩm tương tự từng được sản xuất trước đó.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">3. Ràng buộc Tam giác vàng (Triple Constraints):</strong> Bất kỳ dự án nào cũng chịu sự kiểm soát đồng thời của 3 yếu tố: <em>Thời gian (Time)</em>, <em>Chi phí/Ngân sách (Cost)</em> và <em>Phạm vi/Chất lượng (Scope/Quality)</em>. Sự thay đổi của một yếu tố tất yếu dẫn đến sự điều chỉnh của hai yếu tố còn lại.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">4. Tính bất định và rủi ro cao:</strong> Vì dự án luôn hướng tới tạo ra cái mới trong tương lai nên luôn chứa đựng các rủi ro kỹ thuật, rủi ro thị trường và rủi ro nhân sự.\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">1.3. Chu Kỳ Sống của Dự Án (Project Life Cycle)</h3>\n            <p>\n              Chu kỳ sống của một dự án thông thường trải qua 4 giai đoạn nối tiếp nhau:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-4 gap-2 my-3 text-xs\">\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#8B1E2D]\">Giai đoạn 1</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">Khởi tạo (Initiating)</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Xác định ý tưởng, nghiên cứu tiền khả thi, lập điều lệ dự án (Project Charter) và bổ nhiệm Giám đốc dự án.</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#8B1E2D]\">Giai đoạn 2</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">Lập kế hoạch (Planning)</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Lập WBS, tính toán tiến độ CPM, dự toán ngân sách chi tiết, hoạch định rủi ro và ký kết hợp đồng.</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#8B1E2D]\">Giai đoạn 3</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">Thực hiện &amp; Giám sát (Executing &amp; Monitoring)</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Triển khai gói công việc, quản lý đội ngũ, kiểm soát tiến độ và chi phí bằng phương pháp EVM.</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"font-bold text-[#8B1E2D]\">Giai đoạn 4</span>\n                <p class=\"font-semibold text-gray-800 mt-1\">Kết thúc dự án (Closing)</p>\n                <p class=\"text-[11px] text-gray-500 mt-1\">Nghiệm thu chuyển giao sản phẩm, thanh quyết toán tài chính, lưu trữ hồ sơ và rút ra bài học kinh nghiệm.</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 1 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Thảo luận Chương 1\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Trình bày định nghĩa dự án và phân tích sự khác biệt cốt lõi giữa hoạt động dự án (Project) và hoạt động vận hành thường nhật (Operations).</li>\n              <li>Phân tích mối quan hệ đánh đổi trong \"Tam giác vàng quản trị dự án\" (Triple Constraints). Cho ví dụ thực tế khi chủ đầu tư yêu cầu rút ngắn 30% thời gian thực hiện.</li>\n              <li>Mô tả các công việc trọng tâm trong 4 giai đoạn của chu kỳ sống dự án.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 2: ĐÁNH GIÁ VÀ LỰA CHỌN DỰ ÁN ĐẦU TƯ -->\n      <!-- ========================================== -->\n      <section id=\"chuong-2\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 2 (MH38.02)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">ĐÁNH GIÁ VÀ LỰA CHỌN DỰ ÁN ĐẦU TƯ</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">2.1. Phương Pháp Thời Gian Hoàn Vốn (Payback Period - PP)</h3>\n            <p>\n              Thời gian hoàn vốn là khoảng thời gian cần thiết để tổng thu nhập ròng từ dự án vừa đủ bù đắp lại số vốn đầu tư ban đầu đã bỏ ra:\n            </p>\n            <div class=\"p-4 bg-[#FAF8F6] rounded-lg border-l-4 border-[#8B1E2D] my-3\">\n              <p class=\"font-mono text-center text-sm font-bold text-gray-900\">\n                PP = t - 1 + \\frac{C_0 - \\sum_{k=1}^{t-1} R_k}{R_t}\n              </p>\n              <div class=\"text-xs text-gray-600 mt-2 space-y-1\">\n                <p>Trong đó:</p>\n                <p>• <strong>C₀:</strong> Tổng vốn đầu tư ban đầu của dự án.</p>\n                <p>• <strong>t:</strong> Năm đầu tiên mà lũy kế thu hồi lớn hơn vốn đầu tư.</p>\n                <p>• <strong>Rₜ:</strong> Thu hồi ròng tại năm thứ t (Thu hồi ròng = Lợi nhuận sau thuế + Khấu hao).</p>\n              </div>\n            </div>\n            <p class=\"text-xs text-gray-600 italic\">\n              <strong>Ưu nhược điểm:</strong> PP đơn giản, trực quan, đặc biệt hữu ích cho doanh nghiệp khan hiếm vốn cần quay vòng nhanh. Tuy nhiên, nhược điểm lớn nhất là bỏ qua giá trị thời gian của tiền và không tính đến dòng tiền sinh ra sau thời điểm hoàn vốn.\n            </p>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">2.2. Phương Pháp Hiện Giá Ròng (Net Present Value - NPV)</h3>\n            <p>\n              NPV là chỉ tiêu quan trọng bậc nhất phản ánh giá trị thặng dư ròng mà dự án mang lại cho chủ đầu tư sau khi đã chiết khấu toàn bộ dòng tiền thu hồi và chi phí về thời điểm hiện tại theo lãi suất chiết khấu <em>i</em>:\n            </p>\n            <div class=\"p-4 bg-[#FAF8F6] rounded-lg border-l-4 border-[#8B1E2D] my-3\">\n              <p class=\"font-mono text-center text-sm font-bold text-gray-900\">\n                NPV = \\sum_{t=1}^{n} \\frac{R_t}{(1 + i)^t} - C_0\n              </p>\n              <p class=\"text-xs text-gray-700 mt-2 font-medium\">Quy tắc quyết định lựa chọn dự án:</p>\n              <ul class=\"list-disc list-inside text-xs text-gray-600 pl-2 space-y-1\">\n                <li><strong>NPV &gt; 0:</strong> Chấp thuận dự án (Dự án mang lại giá trị gia tăng thặng dư lớn hơn chi phí sử dụng vốn).</li>\n                <li><strong>NPV = 0:</strong> Dự án hòa vốn về mặt tài chính (vừa đủ bù đắp chi phí cơ hội của vốn).</li>\n                <li><strong>NPV &lt; 0:</strong> Bác bỏ dự án (Dự án làm xói mòn giá trị của doanh nghiệp).</li>\n                <li>Đối với các dự án loại trừ nhau: Chọn dự án có <strong>Max(NPV) &gt; 0</strong>.</li>\n              </ul>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">2.3. Phương Pháp Suất Hoàn Vốn Nội Bộ (Internal Rate of Return - IRR)</h3>\n            <p>\n              IRR là mức lãi suất chiết khấu mà tại đó giá trị hiện giá ròng NPV của dự án triệt tiêu về 0:\n            </p>\n            <div class=\"p-4 bg-[#FAF8F6] rounded-lg border-l-4 border-[#8B1E2D] my-3\">\n              <p class=\"font-mono text-center text-sm font-bold text-gray-900\">\n                NPV(IRR) = \\sum_{t=1}^{n} \\frac{R_t}{(1 + IRR)^t} - C_0 = 0\n              </p>\n              <p class=\"text-xs text-gray-700 mt-2 font-medium\">Công thức nội suy tuyến tính tìm IRR thực tế:</p>\n              <p class=\"font-mono text-center text-xs font-bold text-[#8B1E2D] my-1\">\n                IRR = i_1 + \\frac{NPV_1}{NPV_1 - NPV_2} \\times (i_2 - i_1)\n              </p>\n              <p class=\"text-xs text-gray-500 italic text-center\">\n                (Trong đó chọn i₁ sao cho NPV₁ &gt; 0 và i₂ sao cho NPV₂ &lt; 0, khoảng cách i₂ - i₁ thường lấy trong khoảng 1% - 5%).\n              </p>\n            </div>\n\n            <!-- VÍ DỤ TÍNH TOÁN MINH HỌA CHUẨN XÁC TỪ TÀI LIỆU GỐC -->\n            <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200 my-4 text-xs sm:text-sm space-y-2\">\n              <span class=\"font-bold text-[#8B1E2D] uppercase text-xs\">Ví dụ tính toán số học thực nghiệm (MH38 - Nguồn tài liệu gốc)</span>\n              <p>\n                Một dự án đầu tư có vốn ban đầu (C_0 = 2.000) triệu đồng. Dòng tiền thu hồi ròng trong 3 năm lần lượt là: Năm 1: 500 triệu; Năm 2: 1.200 triệu; Năm 3: 1.500 triệu. Hãy tính IRR của dự án bằng phương pháp nội suy:\n              </p>\n              <ul class=\"list-disc list-inside pl-2 space-y-1 text-gray-700 font-mono text-xs\">\n                <li>Tại (i_1 = 20%): (NPV_1 = \\frac{500}{1.20} + \\frac{1.200}{1.20^2} + \\frac{1.500}{1.20^3} - 2.000 = 416.67 + 833.33 + 868.06 - 2.000 = +118.06) triệu.</li>\n                <li>Tại (i_2 = 24%): (NPV_2 = \\frac{500}{1.24} + \\frac{1.200}{1.24^2} + \\frac{1.500}{1.24^3} - 2.000 = 403.23 + 780.44 + 786.72 - 2.000 = -29.61) triệu.</li>\n                <li>Áp dụng công thức nội suy:\n                  <div class=\"text-[#8B1E2D] font-bold py-1\">\n                    IRR = 20\\% + \\frac{118.06}{118.06 - (-29.61)} \\times (24\\% - 20\\%) = 20\\% + \\frac{118.06}{147.67} \\times 4\\% = 20\\% + 3.198\\% \\approx 23.19\\%\n                  </div>\n                </li>\n              </ul>\n              <p class=\"text-xs text-green-700 font-semibold\">\n                => Kết luận: Với chi phí sử dụng vốn i = 12%, do IRR = 23.19% &gt; i = 12% nên dự án hoàn toàn khả thi và được chấp thuận đầu tư.\n              </p>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">2.4. Chỉ Số Sinh Lợi (Profitability Index - PI)</h3>\n            <p>\n              Chỉ số sinh lợi PI biểu thị giá trị hiện giá của dòng tiền thu hồi được tạo ra trên 1 đồng vốn đầu tư:\n            </p>\n            <div class=\"p-3 bg-gray-50 rounded border text-xs sm:text-sm\">\n              <p class=\"font-mono font-bold text-center text-gray-900\">\n                PI = \\frac{\\sum_{t=1}^{n} \\frac{R_t}{(1 + i)^t}}{C_0} = 1 + \\frac{NPV}{C_0}\n              </p>\n              <p class=\"text-xs text-gray-600 mt-2\">\n                <strong>Quy tắc chấp nhận:</strong> Nếu <strong>PI &gt; 1</strong> (tương đương NPV &gt; 0) thì chấp nhận dự án. Chỉ số PI cực kỳ hữu hiệu khi doanh nghiệp bị giới hạn về trần ngân sách vốn đầu tư cần xếp hạng ưu tiên các dự án.\n              </p>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI VÀ BÀI TẬP CHƯƠNG 2 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Bài tập thực hành Chương 2\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>So sánh ưu điểm và nhược điểm của 4 phương pháp thẩm định tài chính dự án: PP, NPV, IRR và PI.</li>\n              <li>Tại sao trong trường hợp các dự án có quy mô vốn khác nhau hoặc tuổi thọ khác nhau, phương pháp NPV và IRR có thể đưa ra kết luận mâu thuẫn? Trong trường hợp đó nên ưu tiên chỉ tiêu nào?</li>\n              <li><strong>Bài tập tính toán:</strong> Một dự án mở rộng xưởng sản xuất có vốn đầu tư ban đầu (C_0 = 6.000) triệu đồng, dòng tiền ròng thu hồi năm 1: 2.500 triệu; năm 2: 1.640 triệu; năm 3: 4.800 triệu. Hãy tính NPV với chi phí vốn (i = 15%) và tìm IRR của dự án.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 3: TỔ CHỨC DỰ ÁN VÀ ĐỘI NGŨ DỰ ÁN -->\n      <!-- ========================================== -->\n      <section id=\"chuong-3\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 3 (MH38.03)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">TỔ CHỨC DỰ ÁN VÀ ĐỘI NGŨ DỰ ÁN</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">3.1. Các Mô Hình Cơ Cấu Tổ Chức Quản Lý Dự Án</h3>\n            <div class=\"overflow-x-auto my-3 border rounded-lg\">\n              <table class=\"w-full text-left text-xs\">\n                <thead class=\"bg-[#8B1E2D] text-white\">\n                  <tr>\n                    <th class=\"p-3 w-1/4\">Mô hình tổ chức</th>\n                    <th class=\"p-3 w-1/4\">Đặc điểm nhận diện</th>\n                    <th class=\"p-3 w-1/4\">Ưu điểm nổi bật</th>\n                    <th class=\"p-3 w-1/4\">Hạn chế cốt lõi</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200 bg-white\">\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">1. Cơ cấu theo Chức năng (Functional Project)</td>\n                    <td class=\"p-3\">Dự án được phân chia nhỏ và giao về các phòng ban chức năng truyền thống phụ trách.</td>\n                    <td class=\"p-3\">Tận dụng tối đa chuyên môn sâu, không làm xáo trộn cấu trúc công ty mẹ.</td>\n                    <td class=\"p-3\">Dự án thiếu người chịu trách nhiệm duy nhất; phản ứng chậm với khách hàng.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">2. Cơ cấu Chuyên trách (Pure Project)</td>\n                    <td class=\"p-3\">Một ban quản lý dự án độc lập hoàn toàn với giám đốc dự án nắm toàn quyền điều hành.</td>\n                    <td class=\"p-3\">Độ tập trung cao nhất, thông tin thông suốt, ra quyết định cực nhanh.</td>\n                    <td class=\"p-3\">Trùng lặp nguồn lực giữa các dự án; nhân sự lo lắng về việc làm sau khi dự án kết thúc.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">3. Cơ cấu Ma trận (Matrix Organization)</td>\n                    <td class=\"p-3\">Nhân sự thuộc biên chế phòng ban chức năng nhưng được biệt phái vào ban dự án (Ma trận yếu, cân bằng, mạnh).</td>\n                    <td class=\"p-3\">Chia sẻ nguồn lực linh hoạt, tối ưu hóa năng suất lao động toàn công ty.</td>\n                    <td class=\"p-3\">Xung đột thẩm quyền \"hai sếp\" (Giám đốc dự án vs Trưởng phòng chức năng).</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">3.2. Giám Đốc Dự Án (Project Manager - PM)</h3>\n            <p>\n              Giám đốc dự án là người chịu trách nhiệm tối cao và toàn diện trước chủ đầu tư về việc hoàn thành các mục tiêu dự án đúng hạn, trong ngân sách và đạt chất lượng. Bộ năng lực thiết yếu của PM bao gồm:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-2 my-3 text-xs\">\n              <div class=\"p-3 bg-gray-50 rounded border\"><strong>Năng lực Kỹ thuật QLDA:</strong> Kỹ năng lập WBS, kiểm soát tiến độ CPM, phân bổ ngân sách, quản lý rủi ro.</div>\n              <div class=\"p-3 bg-gray-50 rounded border\"><strong>Kỹ năng Lãnh đạo &amp; Con người:</strong> Khả năng truyền cảm hứng, đàm phán giải quyết xung đột, xây dựng tinh thần đồng đội.</div>\n              <div class=\"p-3 bg-gray-50 rounded border\"><strong>Tư duy Chiến lược &amp; Kinh doanh:</strong> Hiểu rõ mục tiêu kinh doanh của tổ chức mẹ và định vị giá trị của sản phẩm dự án trên thị trường.</div>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 3 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Thảo luận Chương 3\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Phân tích sự khác biệt về quyền hạn của Giám đốc dự án trong 3 mô hình ma trận: Ma trận yếu (Weak Matrix), Ma trận cân bằng (Balanced Matrix) và Ma trận mạnh (Strong Matrix).</li>\n              <li>Mô tả 5 giai đoạn phát triển của đội ngũ dự án theo mô hình Bruce Tuckman (Forming, Storming, Norming, Performing, Adjourning).</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 4: LẬP KẾ HOẠCH VÀ NGÂN SÁCH DỰ ÁN -->\n      <!-- ========================================== -->\n      <section id=\"chuong-4\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 4 (MH38.04)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">LẬP KẾ HOẠCH VÀ DỰ TOÁN NGÂN SÁCH DỰ ÁN</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">4.1. Cấu Trúc Phân Chia Công Việc (Work Breakdown Structure - WBS)</h3>\n            <p>\n              WBS là sự phân rã cấu trúc theo cấp bậc của toàn bộ phạm vi công việc cần thực hiện để đạt được các mục tiêu của dự án và tạo ra các kết quả bàn giao (Deliverables):\n            </p>\n            <div class=\"p-4 bg-gray-50 rounded-lg border border-gray-200 text-xs sm:text-sm space-y-2\">\n              <p><strong>Cấp 1:</strong> Mục tiêu chung của Dự án (Project Level).</p>\n              <p><strong>Cấp 2:</strong> Các giai đoạn chính hoặc Sản phẩm bàn giao then chốt (Major Deliverables).</p>\n              <p><strong>Cấp 3:</strong> Các gói phụ trách thành phần (Sub-deliverables).</p>\n              <p><strong>Cấp cuối:</strong> Gói công việc (Work Package) — mức độ chi tiết nhỏ nhất có thể ước tính chính xác về thời gian, chi phí và giao cho một cá nhân chịu trách nhiệm duy nhất.</p>\n              <div class=\"pt-2 text-xs text-[#8B1E2D] font-bold\">\n                * Quy tắc 100%: Tổng các công việc ở cấp con phải bao quát đầy đủ 100% công việc của cấp cha, không trùng lặp và không bỏ sót.\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">4.2. Phương Pháp Dự Toán Ngân Sách Dự Án</h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">1. Dự toán từ trên xuống (Top-down Budgeting):</strong> Ban lãnh đạo cấp cao căn cứ vào kinh nghiệm lịch sử hoặc các dự án tương tự để áp đặt tổng mức ngân sách, sau đó phân bổ xuống cho các cấp quản lý thấp hơn.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">2. Dự toán từ dưới lên (Bottom-up Budgeting):</strong> Dự toán chi phí chi tiết từ từng gói công việc nhỏ nhất (Work Package), sau đó cộng dồn lên từng cấp để hình thành tổng ngân sách dự án. Độ chính xác cao hơn nhưng tốn nhiều thời gian.\n              </div>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 4 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Bài tập thực hành Chương 4\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Trình bày quy tắc 100% trong xây dựng cấu trúc WBS. Tại sao một WBS tốt là tiền đề bắt buộc cho việc lập tiến độ và kiểm soát chi phí?</li>\n              <li>Phân biệt Dự phòng rủi ro (Contingency Reserve) và Dự phòng quản lý (Management Reserve) trong ngân sách dự án.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 5: LẬP TIẾN ĐỘ DỰ ÁN BẰNG SƠ ĐỒ MẠNG -->\n      <!-- ========================================== -->\n      <section id=\"chuong-5\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 5 (MH38.05)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">LẬP TIẾN ĐỘ DỰ ÁN — PHƯƠNG PHÁP ĐƯỜNG GĂNG (CPM) &amp; PERT</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">5.1. Các Công Cụ Thể Hiện Tiến Độ Dự Án</h3>\n            <p>\n              • <strong>Biểu đồ Gantt (Gantt Chart):</strong> Biểu diễn công việc dưới dạng các thanh ngang trên trục thời gian. Ưu điểm: Trực quan, dễ theo dõi, phù hợp báo cáo với ban lãnh đạo. Nhược điểm: Khó thấy rõ mối quan hệ ràng buộc phụ thuộc phức tạp giữa các mắt xích công việc.\n            </p>\n            <p class=\"mt-1\">\n              • <strong>Sơ đồ mạng AOA (Activity on Arrow) &amp; AON (Activity on Node):</strong> Biểu diễn các công việc và sự phụ thuộc logic (Finish-to-Start, Start-to-Start...).\n            </p>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">5.2. Phương Pháp Đường Găng (Critical Path Method - CPM)</h3>\n            <p>\n              Quy trình tính toán đường găng qua 2 bước duyệt mạng:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">Bước 1: Duyệt xuôi từ đầu đến cuối (Forward Pass)</strong>\n                <p class=\"text-xs text-gray-600 mt-1\">Xác định thời điểm khởi sớm (ES) và hoàn thành sớm (EF):</p>\n                <p class=\"font-mono text-xs font-bold text-gray-800 my-1\">EF = ES + t</p>\n                <p class=\"font-mono text-xs font-bold text-gray-800\">ES_{sau} = \\max(EF_{trước})</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">Bước 2: Duyệt ngược từ cuối về đầu (Backward Pass)</strong>\n                <p class=\"text-xs text-gray-600 mt-1\">Xác định thời điểm hoàn thành muộn (LF) và khởi muộn (LS):</p>\n                <p class=\"font-mono text-xs font-bold text-gray-800 my-1\">LS = LF - t</p>\n                <p class=\"font-mono text-xs font-bold text-gray-800\">LF_{trước} = \\min(LS_{sau})</p>\n              </div>\n            </div>\n            <div class=\"p-4 bg-[#FAF8F6] rounded border-l-4 border-[#8B1E2D] text-xs sm:text-sm\">\n              <strong class=\"text-gray-900\">Thời gian dự trữ toàn phần (Total Float / Slack - TF):</strong>\n              <p class=\"font-mono font-bold text-center text-sm text-[#8B1E2D] my-1\">\n                TF = LS - ES = LF - EF\n              </p>\n              <p class=\"text-xs text-gray-700\">\n                • <strong>Đường găng (Critical Path):</strong> Là đường đi xuyên suốt sơ đồ mạng từ nút bắt đầu đến nút kết thúc có <strong>tổng thời gian lớn nhất</strong>, và tất cả các công việc nằm trên đường găng đều có <strong>thời gian dự trữ (TF = 0)</strong>. Bất kỳ sự chậm trễ nào tại công việc găng đều trực tiếp làm chậm trễ tiến độ hoàn thành của toàn bộ dự án.\n              </p>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">5.3. Kỹ Thuật Đánh Giá và Kiểm Tra Dự Án (PERT)</h3>\n            <p>\n              Trong trường hợp thời gian thực hiện công việc có tính bất định, PERT sử dụng phân phối xác suất Beta với 3 ước tính thời gian:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-2 my-2 text-xs\">\n              <div class=\"p-2 bg-gray-50 rounded border\"><strong>a:</strong> Thời gian lạc quan (Optimistic)</div>\n              <div class=\"p-2 bg-gray-50 rounded border\"><strong>m:</strong> Thời gian có khả năng nhất (Most likely)</div>\n              <div class=\"p-2 bg-gray-50 rounded border\"><strong>b:</strong> Thời gian bi quan (Pessimistic)</div>\n            </div>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"text-xs text-gray-500 font-semibold\">Thời gian kỳ vọng bình quân (tₑ)</span>\n                <p class=\"font-mono font-bold text-[#8B1E2D] text-sm mt-1\">t_e = \\frac{a + 4m + b}{6}</p>\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border text-center\">\n                <span class=\"text-xs text-gray-500 font-semibold\">Phương sai thời gian (σ²)</span>\n                <p class=\"font-mono font-bold text-[#8B1E2D] text-sm mt-1\">\\sigma^2 = \\left(\\frac{b - a}{6}\\right)^2</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 5 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Bài tập thực hành Chương 5\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Trình bày định nghĩa đường găng (Critical Path). Tại sao một dự án có thể xuất hiện đồng thời hai đường găng?</li>\n              <li>Giải thích ý nghĩa của thời gian dự trữ toàn phần (Total Float) và thời gian dự trữ tự do (Free Float).</li>\n              <li><strong>Bài tập tính toán PERT:</strong> Một công việc có thời gian lạc quan (a = 4) ngày, có khả năng nhất (m = 7) ngày, bi quan (b = 16) ngày. Tính thời gian kỳ vọng (t_e) và độ lệch chuẩn (\\sigma) của công việc này.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 6: PHÂN BỔ VÀ SAN BẰNG NGUỒN LỰC -->\n      <!-- ========================================== -->\n      <section id=\"chuong-6\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 6 (MH38.06)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">PHÂN BỔ VÀ ĐIỀU HÒA NGUỒN LỰC DỰ ÁN</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">6.1. Khái Niệm và Phân Loại Nguồn Lực Dự Án</h3>\n            <p>\n              Nguồn lực dự án bao gồm 4 yếu tố thiết yếu: <em>Nhân lực (Labor)</em>, <em>Thiết bị máy móc (Equipment)</em>, <em>Nguyên vật liệu (Materials)</em> và <em>Tài chính (Capital)</em>. Trong đó nguồn lực nhân sự kỹ thuật cao và máy móc chuyên dụng thường xuyên bị quá tải hoặc thiếu hụt cục bộ.\n            </p>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">6.2. Kỹ Thuật San Bằng và Điều Hòa Nguồn Lực</h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">1. San bằng nguồn lực (Resource Leveling):</strong> Áp dụng khi nguồn lực bị giới hạn trần cố định không thể bổ sung. Kỹ thuật này dịch chuyển các công việc có thời gian dự trữ ((TF &gt; 0)) hoặc có thể kéo dài tiến độ hoàn thành của dự án nhằm giữ nhu cầu nguồn lực không vượt trần cho phép.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">2. Điều hòa nguồn lực (Resource Smoothing):</strong> Áp dụng khi thời gian kết thúc dự án bị cố định nghiêm ngặt. Người quản trị tận dụng khoảng thời gian dự trữ ((TF)) của các công việc không găng để dịch chuyển thời điểm thực hiện, làm mượt các đỉnh phụ tải nguồn lực mà không kéo dài ngày kết thúc dự án.\n              </div>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 6 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Thảo luận Chương 6\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Phân biệt sự khác nhau giữa kỹ thuật San bằng nguồn lực (Resource Leveling) và Điều hòa nguồn lực (Resource Smoothing).</li>\n              <li>Trình bày các giải pháp xử lý của Giám đốc dự án khi một nguồn lực kỹ sư chuyên gia bị phân bổ trùng lịch trên hai công việc găng đồng thời.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 7: KIỂM SOÁT DỰ ÁN — PHƯƠNG PHÁP EVM -->\n      <!-- ========================================== -->\n      <section id=\"chuong-7\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 7 (MH38.07)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">KIỂM SOÁT DỰ ÁN — KỸ THUẬT QUẢN LÝ GIÁ TRỊ THU ĐƯỢC (EVM)</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">7.1. Bản Chất của Phương Pháp EVM (Earned Value Management)</h3>\n            <p>\n              Kiểm soát chi phí truyền thống chỉ so sánh giữa Chi phí kế hoạch và Chi phí thực chi, do đó dễ gây ngộ nhận: nếu chi ít tiền hơn dự kiến, người quản lý tưởng là tiết kiệm nhưng thực tế có thể dự án đang bị chậm tiến độ nghiêm trọng. Phương pháp EVM khắc phục triệt để bằng cách tích hợp cả 3 biến số: <strong>Phạm vi khối lượng hoàn thành, Thời gian tiến độ và Chi phí tài chính</strong>.\n            </p>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">7.2. Ba Trụ Cột Cơ Bản của EVM</h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-2 my-3 text-xs\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">PV (Planned Value):</strong> Giá trị theo kế hoạch của khối lượng công việc dự kiến hoàn thành đến thời điểm kiểm tra.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">EV (Earned Value):</strong> Giá trị thu được — giá trị kế hoạch của khối lượng công việc thực tế đã hoàn thành tại thời điểm đánh giá.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">AC (Actual Cost):</strong> Chi phí thực tế đã giải ngân để hoàn thành khối lượng công việc thực tế đó.\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">7.3. Các Chỉ Số Đo Lường và Dự Báo EVM Chuẩn Mực</h3>\n            <div class=\"overflow-x-auto my-3 border rounded-lg\">\n              <table class=\"w-full text-left text-xs\">\n                <thead class=\"bg-[#8B1E2D] text-white\">\n                  <tr>\n                    <th class=\"p-3\">Chỉ số EVM</th>\n                    <th class=\"p-3\">Công thức tính</th>\n                    <th class=\"p-3\">Ý nghĩa và Ngưỡng phân tích</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200 bg-white\">\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">Độ lệch Chi phí (Cost Variance - CV)</td>\n                    <td class=\"p-3 font-mono text-[#8B1E2D] font-bold\">CV = EV - AC</td>\n                    <td class=\"p-3\">CV &gt; 0: Tiết kiệm chi phí (dưới ngân sách); CV &lt; 0: Vượt ngân sách (Bội chi).</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">Độ lệch Tiến độ (Schedule Variance - SV)</td>\n                    <td class=\"p-3 font-mono text-[#8B1E2D] font-bold\">SV = EV - PV</td>\n                    <td class=\"p-3\">SV &gt; 0: Nhanh hơn tiến độ kế hoạch; SV &lt; 0: Chậm tiến độ.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">Chỉ số Hiệu quả Chi phí (CPI)</td>\n                    <td class=\"p-3 font-mono text-[#8B1E2D] font-bold\">CPI = EV / AC</td>\n                    <td class=\"p-3\">CPI &gt; 1: Sử dụng chi phí hiệu quả; CPI &lt; 1: Vượt khung chi phí cho phép.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">Chỉ số Hiệu quả Tiến độ (SPI)</td>\n                    <td class=\"p-3 font-mono text-[#8B1E2D] font-bold\">SPI = EV / PV</td>\n                    <td class=\"p-3\">SPI &gt; 1: Tốc độ thực hiện nhanh hơn kế hoạch; SPI &lt; 1: Tốc độ thực hiện chậm trễ.</td>\n                  </tr>\n                  <tr>\n                    <td class=\"p-3 font-bold text-gray-900\">Dự báo Tổng chi phí hoàn thành (EAC)</td>\n                    <td class=\"p-3 font-mono text-[#8B1E2D] font-bold\">EAC = BAC / CPI</td>\n                    <td class=\"p-3\">Dự báo tổng ngân sách cần chi trả khi kết thúc dự án (với BAC là tổng ngân sách kế hoạch ban đầu).</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 7 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Bài tập thực hành Chương 7\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Tại sao nói kỹ thuật EVM khắc phục được nhược điểm cốt tử của phương pháp kiểm soát tài chính kế toán truyền thống?</li>\n              <li><strong>Bài tập tính toán EVM:</strong> Một gói thầu phần mềm có tổng ngân sách được duyệt (BAC = 100.000) USD, thời gian kế hoạch 10 tháng. Đến cuối tháng thứ 6, theo kế hoạch phải hoàn thành 60% dự án ((PV = 60.000) USD). Trên thực tế nhóm chỉ hoàn thành 50% khối lượng công việc ((EV = 50.000) USD) và đã chi hết (AC = 65.000) USD. Hãy tính CV, SV, CPI, SPI và dự báo tổng chi phí khi hoàn thành (EAC). Nhận xét tình trạng của dự án.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- CHƯƠNG 8: ĐÁNH GIÁ VÀ KẾT THÚC DỰ ÁN -->\n      <!-- ========================================== -->\n      <section id=\"chuong-8\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-6\">\n        <div class=\"border-b-2 border-[#8B1E2D] pb-3\">\n          <span class=\"text-xs font-bold text-[#8B1E2D] uppercase tracking-wider\">Chương 8 (MH38.08)</span>\n          <h2 class=\"text-2xl font-black text-[#111827] mt-1\">ĐÁNH GIÁ VÀ KẾT THÚC DỰ ÁN</h2>\n        </div>\n\n        <div class=\"space-y-6 text-sm sm:text-base text-gray-700\">\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">8.1. Các Hình Thức Kết Thúc Dự Án</h3>\n            <p>\n              Một dự án có thể kết thúc theo 4 hình thức chính trong thực tế quản trị:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 my-3 text-xs sm:text-sm\">\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">1. Kết thúc do Tuyệt đối hoàn thành (Extinction):</strong> Toàn bộ các công việc đã được nghiệm thu hoàn tất thành công, sản phẩm được bàn giao trọn vẹn cho khách hàng hoặc tổ chức vận hành.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">2. Kết thúc do Hòa nhập vào tổ chức mẹ (Addition):</strong> Dự án phát triển thành một đơn vị kinh doanh mới (SBU) hoặc một phòng ban thường trực trong tổ chức mẹ.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">3. Kết thúc do Tích hợp (Integration):</strong> Các nguồn lực tài sản, nhân sự của dự án được phân bổ, phân tán trở lại các phòng ban chức năng mẹ.\n              </div>\n              <div class=\"p-3 bg-gray-50 rounded border\">\n                <strong class=\"text-[#8B1E2D]\">4. Kết thúc do Cắt nguồn lực / Đình chỉ (Starvation/Termination):</strong> Dự án bị cắt giảm ngân sách dần hoặc dừng khẩn cấp do thị trường thay đổi, công nghệ lỗi thời hoặc cạn kiệt tài chính.\n              </div>\n            </div>\n          </div>\n\n          <div>\n            <h3 class=\"text-lg font-bold text-[#8B1E2D] mb-2\">8.2. Thủ Tục Nghiệm Thu và Báo Cáo Tổng Kết Dự Án</h3>\n            <p>\n              Quy trình đóng dự án đòi hỏi thực hiện nghiêm túc 4 thủ tục hành chính - kỹ thuật bắt buộc:\n            </p>\n            <ul class=\"list-disc list-inside space-y-1 text-xs sm:text-sm pl-2\">\n              <li><strong>Nghiệm thu chuyển giao sản phẩm:</strong> Ký kết biên bản bàn giao chính thức với khách hàng hoặc chủ đầu tư.</li>\n              <li><strong>Thanh quyết toán tài chính:</strong> Khóa sổ sách kế toán dự án, quyết toán các hợp đồng thầu phụ, thanh lý bảo lãnh hợp đồng.</li>\n              <li><strong>Giải phóng nguồn lực &amp; Nhân sự:</strong> Đánh giá thành tích cá nhân, thực hiện khen thưởng và bàn giao nhân sự về đơn vị mẹ.</li>\n              <li><strong>Báo cáo tổng kết dự án &amp; Bài học kinh nghiệm (Lessons Learned):</strong> Lưu trữ toàn bộ tài liệu dự án vào hệ thống tài sản quy trình tổ chức (OPA) để làm giàu cơ sở dữ liệu tri thức cho các dự án tương lai.</li>\n            </ul>\n          </div>\n\n          <!-- CÂU HỎI ÔN TẬP CHƯƠNG 8 -->\n          <div class=\"mt-6 pt-4 border-t border-gray-200\">\n            <h4 class=\"font-bold text-gray-900 text-sm mb-3 uppercase tracking-wider flex items-center gap-2\">\n              <span class=\"w-5 h-5 rounded bg-[#8B1E2D] text-white flex items-center justify-center text-xs\">?</span>\n              Câu hỏi ôn tập &amp; Đánh giá tổng hợp Chương 8\n            </h4>\n            <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n              <li>Trình bày 4 hình thức kết thúc dự án và cho ví dụ minh họa thực tế cho từng hình thức.</li>\n              <li>Tại sao khâu tổng kết bài học kinh nghiệm (Lessons Learned) thường bị các giám đốc dự án bỏ qua hoặc làm chiếu lệ? Điều này gây thiệt hại gì cho tổ chức mẹ?</li>\n              <li>Nêu các nhiệm vụ chính của một Giám đốc dự án trong giai đoạn đóng dự án về mặt hợp đồng và tài chính.</li>\n            </ol>\n          </div>\n        </div>\n      </section>\n\n      <!-- ========================================== -->\n      <!-- TÀI LIỆU THAM KHẢO CHÍNH THỨC -->\n      <!-- ========================================== -->\n      <section id=\"tai-lieu-tham-khao\" class=\"bg-white rounded-xl shadow-sm border border-[#E5E7EB] p-6 sm:p-8 space-y-4\">\n        <h3 class=\"text-base font-bold text-[#8B1E2D] uppercase tracking-wider border-b border-gray-100 pb-2\">\n          Tài Liệu Tham Khảo Học Thuật Chuẩn\n        </h3>\n        <ol class=\"list-decimal list-inside space-y-2 text-xs sm:text-sm text-gray-700\">\n          <li><strong>ThS. Nguyễn Thị Trúc Phương</strong> (Chủ biên), <em>Giáo trình Quản trị dự án (MH38)</em>, Khoa Quản trị kinh doanh, Trường Cao đẳng Kinh tế Thành phố Hồ Chí Minh.</li>\n          <li><strong>Project Management Institute - PMI</strong> (2021), <em>A Guide to the Project Management Body of Knowledge (PMBOK® Guide)</em> (7th Edition).</li>\n          <li><strong>Jack R. Meredith, Samuel J. Mantel Jr. &amp; Scott M. Shafer</strong> (2021), <em>Project Management: A Managerial Approach</em> (11th Edition), Wiley.</li>\n          <li><strong>Harold Kerzner</strong> (2017), <em>Project Management: A Systems Approach to Planning, Scheduling, and Controlling</em> (12th Edition), Wiley.</li>\n          <li><strong>Clifford F. Gray &amp; Erik W. Larson</strong> (2020), <em>Project Management: The Managerial Process</em> (8th Edition), McGraw-Hill Education.</li>\n        </ol>\n      </section>\n\n    </main>\n\n    <!-- FOOTER TRANG HỌC LIỆU SỐ -->\n    <footer class=\"no-print w-full bg-[#111827] text-gray-400 py-8 px-4 text-center text-xs space-y-2 border-t-2 border-[#8B1E2D]\">\n      <p class=\"text-white font-medium\">BẢN QUYỀN HỌC LIỆU SỐ THUỘC VỀ KHOA QUẢN TRỊ KINH DOANH — GIẢNG VIÊN ThS. NGUYỄN THỊ TRÚC PHƯƠNG</p>\n      <p>Hệ thống số hóa giáo trình phục vụ công tác đào tạo chính quy trình độ Cao đẳng &amp; Đại học.</p>\n    </footer>\n\n  </div>\n  ";
